.pay-grid>div:first-child .section-label{order:1}.pay-grid>div:first-child .account-type{order:2}.pay-grid>div:first-child .phone{order:3}.pay-grid>div:first-child .recipient-name{order:4}.pay-grid>div:first-child .phone{justify-content:center}.pay-grid>div:first-child .recipient-name{justify-content:center}.divider{height:190px;background:var(--line);position:relative}.divider span{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;border:1px solid var(--line);border-radius:50%;padding:10px 8px;font-size:10px;font-weight:700;color:var(--pink)}.section-label,.field label{font-size:13px;color:var(--muted);font-weight:600}.recipient{display:flex;flex-direction:column;gap:8px;align-items:center;margin:15px 0 3px}.recipient strong{font-size:16px}.verified{color:#2F80ED;font-size:16px}.recipient strong,.recipient .verified{margin-top:0}.recipient-name{display:flex;align-items:center;justify-content:center;gap:6px}.account-name{color:#fff;background:#0B0E11;border-radius:10px;padding:5px}.account-type{font-size:12px;color:var(--muted);margin-top:5px;margin-bottom:-2px}.recipient strong{display:inline-block}.recipient .verified{margin-left:0}.phone{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:188px;width:100%;background:transparent;border:0;border-top:0;border-bottom:0;border-radius:0;padding:12px 14px;font-size:16px;font-weight:600}.phone-number{white-space:nowrap}.phone-number strong{font-size:18px;font-weight:700}.phone>i{font-size:16px}.copy{position:static;border:0;background:none;color:var(--pink);cursor:pointer;font:600 12px Inter;padding:0;margin-left:8px}.scan{text-align:center}.scan h2{font-size:14px;color:var(--muted);font-weight:400;margin:0 0 8px}.qr-frame{position:relative;width:158px;height:158px;margin:auto;padding:4px}.qr-frame:before{content:'';position:absolute;z-index:2;inset:0;pointer-events:none;background:linear-gradient(var(--pink),var(--pink)) top left/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) top left/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) top right/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) top right/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom left/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom left/3px 18px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom right/18px 3px no-repeat,linear-gradient(var(--pink),var(--pink)) bottom right/3px 18px no-repeat;border-radius:0}.qr{position:relative;z-index:1;display:block;width:150px;height:150px;padding:5px;margin:auto;border:0;border-radius:0;box-shadow:none;background:#fff}.email-badge{display:inline-flex;align-items:center;gap:8px;max-width:100%;padding:14px;border:1px solid var(--line);border-radius:14px;background:#FCFCFD;font-size:13px;font-weight:600;word-break:break-all}.email-badge .copy{color:var(--pink)}.form-area{border-top:1px solid var(--line);margin-top:30px;padding-top:26px}.field{margin-bottom:18px}.field label{display:block;margin-bottom:8px;color:var(--ink)}.input-wrap{position:relative}.input-wrap i{position:absolute;left:17px;top:50%;transform:translateY(-50%);color:#A2A6AD;font-size:15px;line-height:1;z-index:1}.input{width:100%;height:54px;border:1px solid var(--line);border-radius:15px;padding:0 18px 0 46px;line-height:54px;font:inherit;outline:0;background:#FCFCFD}.input:focus{border-color:var(--pink);box-shadow:0 0 0 4px rgba(240,185,11,.14)}.btn-pay{width:100%;height:auto;padding:15px 20px;border:0;border-radius:16px;background:linear-gradient(100deg,var(--pink),var(--pink2));color:#0B0E11;font:700 14px Inter;cursor:pointer;box-shadow:0 10px 20px rgba(240,185,11,.22);transition:.2s}.btn-pay:hover{filter:brightness(1.05);box-shadow:0 12px 26px rgba(240,185,11,.3)}.response{display:block;margin-bottom:12px}.alert{padding:12px;border-radius:12px;font-size:13px;background:#fff0f0;color:#c0392b}.response-message{padding:11px 13px;border-radius:10px;background:#fff1f1;color:#b52e38;font-size:13px;font-weight:600}.upload-section{border-top:1px solid var(--line);margin-top:30px;padding-top:26px}.upload-label{display:block;margin-bottom:10px;color:var(--ink);font-size:13px;font-weight:700}.upload-box{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px 14px;min-height:96px;padding:14px 16px;border:1.5px dashed #E8C65C;border-radius:16px;background:#FBFCF9;text-align:left;transition:border-color .2s,background .2s}.upload-box:hover,.upload-box.has-file{border-color:var(--pink);background:#FFF9E6}.upload-copy{display:flex;align-items:center;min-width:0;gap:10px}.upload-icon{display:grid;flex:0 0 auto;width:34px;height:34px;place-items:center;border-radius:10px;background:#FFF3D6;color:var(--pink)}.upload-icon i{font-size:16px}.upload-title{margin:0;color:#263958;font-size:13px;font-weight:700;white-space:nowrap}.choose-file{display:inline-flex;align-items:center;justify-content:center;align-self:center;padding:9px 14px;border:1px solid #E8C65C;border-radius:9px;background:#fff;color:var(--pink);font-size:12px;font-weight:700;white-space:nowrap;transition:border-color .2s,background .2s}.choose-file:hover{border-color:var(--pink);background:#FFF3D6}.file-helper{grid-column:1;grid-row:2;align-self:center;margin:0 0 0 44px;color:#9aa7ba;font-size:10px}.file-name{grid-column:1 / -1;max-width:100%;margin:0;overflow:hidden;color:#118935;font-size:12px;font-weight:700;text-overflow:ellipsis;white-space:nowrap}.payment-id{display:none}.footer{text-align:center;color:#9a9da3;font-size:12px;margin-top:22px}@media(max-width:600px){.page{width:calc(100% - 16px);margin:10px auto 24px;padding:0 14px 18px}.main{padding:16px}.pay-grid{grid-template-columns:1fr;gap:16px}.divider{height:1px;width:100%}.divider span{padding:7px 10px}.price{font-size:28px;letter-spacing:-1px;margin-top:2px}.amount{padding:16px 20px}.top{margin-bottom:10px;padding:12px 14px 0 !important}.form-area{margin-top:18px;padding-top:16px}.field{margin-bottom:13px}.input{height:48px;line-height:48px}.footer{margin-top:14px}.upload-box{grid-template-columns:1fr;gap:8px;min-height:auto}.upload-copy{justify-content:center}.upload-title{white-space:normal;text-align:center}.choose-file{justify-self:center;margin-left:0}.file-helper{grid-column:1;margin-left:0;text-align:center}}
</style></head>
<body><main class="page"><header class="top" style="padding:18px 20px 0"><button class="back" onclick="location.href='<?php echo pp_get_paymentlink($payment_id)?>'" aria-label="Back"><i class="fa-solid fa-arrow-left"></i><span>Back</span></button><img src="<?php echo $logo?>" alt="Binance"><span aria-hidden="true"></span></header>
<section class="card amount"><div class="eyebrow">Amount to Pay</div><div class="price"><?php echo $amount?></div></section>
<section class="card main"><div class="pay-grid"><div><div class="recipient"><div class="section-label">Send To</div><div class="account-type">Binance User</div><div class="recipient-name account-name"><strong><?php echo htmlspecialchars($binance_email_id);?></strong></div></div><div class="phone"><span class="phone-number recipient-name"><strong><?php echo htmlspecialchars($amount);?></strong></span></div></div><div class="divider"><span>OR</span></div>
<?php if(!empty($settings['qr_code'])): ?><div class="scan"><h2>Scan to Pay</h2><div class="qr-frame"><img class="qr" src="<?php echo htmlspecialchars($settings['qr_code']);?>" alt="Payment QR code"></div></div><?php else: ?><div class="scan"><h2>Recipient Email / ID</h2><div class="email-badge"><span><?php echo htmlspecialchars($binance_email_id);?></span><button class="copy" onclick="copyText('<?php echo htmlspecialchars($binance_email_id, ENT_QUOTES);?>',this)" aria-label="Copy email"><i class="fa-regular fa-copy"></i></button></div></div><?php endif; ?></div>
<div class="upload-section">
                <div class="upload-label" id="payment-slip-label">Upload payment receipt</div>
                    <label class="upload-box" for="payment-slip">
                    <span class="upload-copy"><span class="upload-icon"><i class="fa-solid fa-cloud-arrow-up"></i></span><span class="upload-title">Drop your receipt here</span></span>
                    <span class="choose-file">Choose File</span>
                    <span class="file-helper">JPG • PNG • PDF • Max 5MB</span>
                    <span class="file-name" aria-live="polite"></span>
                </label>
                <input id="payment-slip" name="payment-slip" class="payment-id" type="file" accept="image/jpeg,image/png,application/pdf" aria-labelledby="payment-slip-label">
            </div>

            <span class="response" aria-live="polite"></span>
            <button type="button" class="btn-pay"><i class="fa-solid fa-shield-halved" aria-hidden="true"></i><span>Verify</span></button>
            </div></section><footer class="footer">Secure payment verification · Powered by <strong>KeyClan</strong></footer></main>
<script>
function copyText(text,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(function(){var original=button.innerHTML;button.innerHTML='<i class="fa-solid fa-check"></i>';button.disabled=true;setTimeout(function(){button.innerHTML=original;button.disabled=false},2000)})}}
const fileInput=document.querySelector('.payment-id');const uploadBox=document.querySelector('.upload-box');const fileName=document.querySelector('.file-name');const verifyButton=document.querySelector('.btn-pay');const response=document.querySelector('.response');
fileInput.addEventListener('change',function(){const file=this.files[0];if(!file)return;uploadBox.classList.add('has-file');fileName.textContent=file.name});
verifyButton.addEventListener('click',function(){const file=fileInput.files[0];response.innerHTML='';if(!file){response.innerHTML='<div class="response-message">Please upload your payment receipt before verifying.</div>';return}if(file.size>5*1024*1024){response.innerHTML='<div class="response-message">Your receipt must be smaller than 5MB.</div>';return}verifyButton.disabled=true;verifyButton.querySelector('span').textContent='Verifying receipt…';const formData=new FormData();formData.append('binance-manual','<?php echo $payment_id?>');formData.append('payment_slip',file);formData.append('binance_email_id','<?php echo htmlspecialchars($binance_email_id, ENT_QUOTES);?>');$.ajax({type:'POST',url:'<?php echo pp_get_paymentlink($payment_id)?>?method=binance-manual',data:formData,contentType:false,processData:false,success:function(data){try{const result=JSON.parse(data);if(result.status==='false'){response.innerHTML='<div class="response-message">'+result.message+'</div>';verifyButton.disabled=false;verifyButton.querySelector('span').textContent='Verify'}else location.href='<?php echo pp_get_paymentlink($payment_id)?>'}catch(error){response.innerHTML='<div class="response-message">Unable to process the receipt. Please try again.</div>';verifyButton.disabled=false;verifyButton.querySelector('span').textContent='Verify'}},error:function(){response.innerHTML='<div class="response-message">Unable to upload the receipt. Please try again.</div>';verifyButton.disabled=false;verifyButton.querySelector('span').textContent='Verify'}})})
</script></body></html>